import{c as o,J as a,h as r,k as s}from"./chunks/framework.WgZQdPFo.js";const g=JSON.parse('{"title":"Счета и кошельки","description":"Учет наличных денег, банковских карт, вкладов, валютных счетов и стейблкоинов в пространстве «Мой капитал».","frontmatter":{"title":"Счета и кошельки","description":"Учет наличных денег, банковских карт, вкладов, валютных счетов и стейблкоинов в пространстве «Мой капитал».","order":17},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/accounts.md","filePath":"ru/docs/spaces/moy-kapital/accounts.md"}'),l={name:"ru/docs/spaces/moy-kapital/accounts.md"};function i(e,t,n,c,p,d){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="счета-и-кошельки" tabindex="-1">Счета и кошельки <a class="header-anchor" href="#счета-и-кошельки" aria-label="Permalink to &quot;Счета и кошельки&quot;">​</a></h1><p>Вкладка <strong>«Счета и кошельки»</strong> — это стартовая точка ликвидного контура мастера в пространстве «Мой капитал». Здесь фиксируются все доступные денежные средства, которые не задействованы непосредственно в операционном цикле мастерской: наличные в кармане и сейфе, дебетовые карты, депозиты, валютные запасы и расчетные стейблкоины (USDT, USDC).</p><hr><h2 id="два-режима-добавления-одиночныи-счет-и-группа" tabindex="-1">Два режима добавления: одиночный счет и группа <a class="header-anchor" href="#два-режима-добавления-одиночныи-счет-и-группа" aria-label="Permalink to &quot;Два режима добавления: одиночный счет и группа&quot;">​</a></h2><p>При нажатии кнопки <strong>«Добавить»</strong> в правом верхнем углу вкладки открывается модальное окно с переключателем режимов:</p><ol><li><strong>Одиночный счет:</strong> лаконичная форма для независимых счетов (например, отдельная кредитная карта, наличные средства в кошельке или накопительный конверт).</li><li><strong>Группа / Банк / Хранилище:</strong> мультивалютный контейнер, позволяющий за один прием внести в систему банк целиком со всеми открытыми в нем счетами (рублевая карта, валютный счет, накопительный вклад).</li></ol><div class="tip custom-block"><p class="custom-block-title">Быстрое добавление нескольких валют</p><p>В режиме группы форма оснащена кнопкой <strong>«Добавить еще валюту / счет в группу»</strong>. Вы можете динамически прикрепить к одному банку любое количество счетов с индивидуальными остатками, валютами и комментариями.</p></div><hr><h2 id="мультивалютность-и-компоновка-формы" tabindex="-1">Мультивалютность и компоновка формы <a class="header-anchor" href="#мультивалютность-и-компоновка-формы" aria-label="Permalink to &quot;Мультивалютность и компоновка формы&quot;">​</a></h2><p>Для каждого счета указывается:</p><ul><li><strong>Наименование счета:</strong> понятное имя («Основная дебетовая карта», «Накопительный счет 16%», «Кошелек наличных»).</li><li><strong>Тип счета:</strong> функциональный классификатор («Карта», «Вклад», «Наличные», «Электронный кошелек», «Криптовалюта»). По умолчанию создается статус <em>«Без категории»</em>. Справочник типов настраивается прямо из окна через кнопку с иконкой карандаша.</li><li><strong>Валюта и курс пересчета:</strong> выбор из стандартного перечня мировых валют либо ввод собственного тикера. Если валюта счета отличается от базовой валюты капитала, форма автоматически открывает поле курса.</li><li><strong>Остаток и курс в одну строку:</strong> в форме добавления и редактирования поля остатка и курса скомпонованы компактно в единый горизонтальный ряд.</li></ul><div class="info custom-block"><p class="custom-block-title">Правило курса валюты</p><p>Для счетов в базовой валюте курс всегда равен $1{,}00$ и поле курса скрыто. Для иностранной валюты задается курс к базовой единице (например, $1\\text{ USD} = 93{,}50\\text{ ₽}$). При изменении курса в централизованном диалоге все рублевые эквиваленты пересчитываются автоматически.</p></div><hr><h2 id="карточки-групп-и-сводныи-баланс" tabindex="-1">Карточки групп и сводный баланс <a class="header-anchor" href="#карточки-групп-и-сводныи-баланс" aria-label="Permalink to &quot;Карточки групп и сводный баланс&quot;">​</a></h2><p>Счета с одинаковым именем группы автоматически объединяются программой в наглядные сводные карточки:</p><ul><li><strong>Заголовок группы:</strong> название банка или финансового учреждения, бейдж категории («Банки и вклады», «Криптокошельки») и индикатор количества счетов.</li><li><strong>Совокупный остаток группы:</strong> сумма всех счетов внутри группы, автоматически приведенная к базовой валюте по действующим курсам.</li><li><strong>Строки счетов:</strong> список позиций с балансом в оригинальной валюте, эквивалентом в базовой валюте, ссылкой на онлайн-банк и примечаниями.</li></ul><h3 id="деиствия-в-шапке-карточки-группы" tabindex="-1">Действия в шапке карточки группы <a class="header-anchor" href="#деиствия-в-шапке-карточки-группы" aria-label="Permalink to &quot;Действия в шапке карточки группы&quot;">​</a></h3><p>В правом верхнем углу карточки группы расположен компактный блок управления:</p><ul><li><strong>Кнопка «+» (Быстрое добавление):</strong> мгновенно открывает диалог добавления нового счета с уже подставленным именем этой группы.</li><li><strong>Стрелки ↑ и ↓ (Упорядочивание):</strong> ручное перемещение карточки группы выше или ниже в общем реестре. Неактивные стрелки у крайних элементов окрашиваются в нейтральный приглушенный цвет для визуального порядка.</li><li><strong>Кнопка с карандашом (Управление группой):</strong> открывает диалоговое окно для комплексного редактирования: переименование с каскадным обновлением всех связанных счетов, смена категории группы и сортировка позиций внутри банка.</li></ul><hr><h2 id="виды-отображения-плитка-и-полосы" tabindex="-1">Виды отображения: плитка и полосы <a class="header-anchor" href="#виды-отображения-плитка-и-полосы" aria-label="Permalink to &quot;Виды отображения: плитка и полосы&quot;">​</a></h2><p>На панели инструментов вкладки расположен переключатель плотности интерфейса:</p><ul><li><strong>Плитка (Колонки):</strong> просторная блочная сетка, идеальная для широких мониторов. Карточки группируются по категориям в адаптивные колонки с сохранением естественной высоты.</li><li><strong>Полосы (Плотный список):</strong> компактный вертикальный реестр для быстрой ревизии счетов. Каждая группа представлена лаконичной строкой с возможностью раскрытия состава по клику.</li></ul><div class="tip custom-block"><p class="custom-block-title">Глобальное раскрытие списков</p><p>Кнопка <strong>«↕»</strong> на панели инструментов позволяет в один клик свернуть или развернуть все группы счетов одновременно.</p></div><hr><h2 id="архив-и-безопасное-удаление-счетов" tabindex="-1">Архив и безопасное удаление счетов <a class="header-anchor" href="#архив-и-безопасное-удаление-счетов" aria-label="Permalink to &quot;Архив и безопасное удаление счетов&quot;">​</a></h2><p>Если счет закрыт в банке или карта заблокирована, удалять запись из базы не требуется — достаточно отправить ее в архив:</p><ol><li>Откройте окно редактирования счета или нажмите кнопку меню на карточке счета.</li><li>Выберите действие <strong>«В архив»</strong>. Счет исчезнет из активного списка и перестанет влиять на текущую ликвидность.</li><li>Группа счетов автоматически скрывается из активного экрана, если все входящие в нее счета перенесены в архив.</li></ol><p>Для просмотра архивных записей нажмите кнопку <strong>«Архив»</strong> на панели инструментов. В архивном режиме счета можно восстановить в активный учет либо удалить физически (с проверкой мягкого удаления <code>is_deleted = 1</code>).</p>',29)])])}const u=o(l,[["render",i]]);export{g as __pageData,u as default};
